def transform(grid):
    import itertools
    g = np.array(grid)
    bg = background(g)
    colors = [int(c) for c in np.unique(g) if c != bg]
    yy, xx = np.indices(g.shape)
    coords = [yy, xx, yy - xx, yy + xx]
    masks = {}
    for c in colors:
        v = g == c
        cands = []
        for co in coords:
            vals = np.unique(co[v])
            if len(vals) == 1:
                cands.append(co == vals[0])
        masks[c] = cands[0] if cands else v
    valid, chain = [], []
    for order in itertools.permutations(colors):
        p = np.full_like(g, bg)
        for c in order:
            p[masks[c]] = c
        if np.array_equal(p, g):
            valid.append(order)
            if all(int((masks[a] & masks[b]).sum()) == 1 for a, b in zip(order, order[1:])):
                chain.append(order)
    order = chain[0] if chain else (valid[0] if valid else tuple(colors))
    out = np.full((1, len(order)), bg, dtype=int)
    emit(out, 'Allocate one output slot per coloured line, ordered from bottom layer to top layer.')
    for i, c in enumerate(order):
        out[0, i] = c
        emit(out, f'Slot {i}: colour {c}, the next line in the painting order that reproduces every visible crossing.')
    return out
